"""Explicit candidate assembly. Global source-bank transforms, no fitted animation frames."""
from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parent
views=['S','SW','W','NW','N','NE','E','SE'];four=['S','W','N','E'];items=[]
def frame(path,cell=0,scale=1,tx=0,ty=0,source_rect=None):
 return {'path':path,'cell':cell,'source_rect':source_rect,'scale':scale,'translation':[tx+32,ty],'sha256':hashlib.sha256((P/path).read_bytes()).hexdigest()}
def add(action,view,frames,times,notes):items.append({'action':action,'view':view,'frames':frames,'durations_ms':times,'assembly_notes':notes,'status':'candidate_requires_actual_review'})
ns=398/408;ntx=224-222*ns;nty=490-488*ns
neutral={v:frame(f'neutral/{v}.png') for v in views}
neutral['N']=frame('../ro-motion-lab-v51/pickup-body/00.png',scale=ns,tx=ntx,ty=nty)
for i,v in enumerate(views):
 add('idle',v,[neutral[v]],[1000],'Static neutral; N locks the exact same source pose as pickup, one bank-scale399px calibration. Other seven native turnaround views unchanged.')
 # Two row origins represent static atlas packing, not an animation registration fit.
 add('sit',v,[frame('raw/sit-eight-attempt1.png',i,.78,224-224*.78,123.84 if i<4 else 160.5)],[1000],'Static grounded seat; one whole-bank .78 scale from complete-head calibration, two shared row origins. No transition or automatic hidden-joint claim.')
for j,v in enumerate(four):
 add('ready',v,[frame('raw/ready-head-repair2.png',j)],[1000],'Static guard from native repaired bank; first bank rejected for clipped boots. No duplicated breathing drawings claimed.')
 # Native hurt bank remains a rejected study. Use source-projected small motion after export.
 add('dead',v,[frame('raw/dead-wardrobe-repair2.png' if v in ['S','N'] else 'raw/dead-four-attempt1.png',j,source_rect=[0,0,416,512] if v=='S' else None)],[1000],'Terminal defeat pose only. S and N use wardrobe repair; W/E retain original bank. S cape extends10px beyond original cell into verified-empty gutter, so explicit416px source rectangle retains it on512px logical canvas. Earlier collapse studies unselected; no falling transition claim.')
 add('skill',v,[neutral[v],frame('raw/skill-four-attempt1.png',j),frame('raw/skill-four-attempt1.png',j+4,ty=16),neutral[v]],[100,220,180,300],'RIGHT-hand generic cast; bottomrow shared+16 packing origin. Lead foot may step and rear heel release during cast; not all-feet-planted pickup gate. No baked effects.')
reaction=P/'light-reaction-qa.json'
if reaction.is_file():
 for v,r in json.loads(reaction.read_text())['views'].items():
  add('hurt',v,[frame(f'light-reactions/{v}/{i:02}.png',tx=-32,source_rect=[0,0,512,512]) for i in range(16)],r['durations_ms'],'Small-motion rest-mesh recoil from actual external CC0 source world deltas projected by physical camera. Not16 new native drawings; distal band exact and head rigid, no individual frame fitting. Rendered neutral may differ by WebGL sampling rounding; transition pixel comparison required.')
add('pickup','N',[frame(f'../ro-motion-lab-v51/pickup-body/{i:02}.png',scale=ns,tx=ntx,ty=nty) for i in range(16)],[90]*15+[550],'Exact current native-cleanup16 bank, one neutral-only scale/translation applied to every frame. Last whole pose aliases first. No per-frame fitting. Generic RO-like pickup, empty hands and separate world item event; hidden grasp not proven.')
data={'canvas':[512,512],'items':items,'source_scale_policy':'Static source-bank authoring calibration and explicit row-packing metadata, never per-key fitted coordinates','production_pass':False}
(P/'stage-manifest.json').write_text(json.dumps(data,indent=2)+'\n')
html='''<!doctype html><html lang="th"><meta charset="utf-8"><title>ตรวจชุดท่าและทิศ</title><style>body{background:#20252d;color:#eee;font:16px system-ui;margin:20px}canvas{background:#292b30;max-height:72vh}button,select,input{font:inherit;margin:5px}p{max-width:900px}</style><h1>ชุดท่าและทิศ · กำลังตรวจ</h1><p>พรีวิวชุดภาพจริง · เลือกท่าและมุมเพื่อดูการกลับมายืน · ท่าที่ไม่มีภาพจะไม่แสดงเป็นผ่าน</p><select id="clip"></select><select id="speed"><option value="1">1×</option><option value="0.25">¼×</option></select><button id="play">เล่น / หยุด</button><label><input id="loop" type="checkbox" checked>วน</label><div><canvas id="c" width="512" height="512"></canvas></div><input id="frame" type="range" min="0" max="0" value="0"><p id="status"></p><script>const D=__DATA__,c=document.getElementById('c'),x=c.getContext('2d'),cache=new Map(),sel=document.getElementById('clip'),slider=document.getElementById('frame');let ci=0,fi=0,playing=false,time=0,last=0,loops=0;D.items.forEach((a,i)=>sel.add(new Option(a.action+' · '+a.view,i)));function draw(i=ci,k=fi){const a=D.items[i],f=a.frames[k],im=cache.get(f.path),s=f.scale,[tx,ty]=f.translation;x.setTransform(1,0,0,1,0,0);x.clearRect(0,0,512,512);let col=f.cell%4,row=Math.floor(f.cell/4),r=f.source_rect||[col*384,row*512,384,512];x.drawImage(im,...r,tx,ty,r[2]*s,r[3]*s);document.getElementById('status').textContent=a.action+' '+a.view+' · '+(k+1)+'/'+a.frames.length;slider.value=k}function choose(i){ci=i;fi=0;time=0;playing=false;slider.max=D.items[i].frames.length-1;draw()}sel.onchange=()=>choose(+sel.value);slider.oninput=()=>{playing=false;fi=+slider.value;draw()};document.getElementById('play').onclick=()=>{playing=!playing;last=performance.now()};function tick(now){if(playing){const a=D.items[ci],total=a.durations_ms.reduce((a,b)=>a+b,0);time+=(now-last)*+document.getElementById('speed').value;if(time>=total){if(document.getElementById('loop').checked){loops+=Math.floor(time/total);time%=total}else{time=total-.001;playing=false}}let t=time;fi=0;while(fi<a.frames.length-1&&t>=a.durations_ms[fi])t-=a.durations_ms[fi++];draw()}last=now;requestAnimationFrame(tick)}Promise.all([...new Set(D.items.flatMap(a=>a.frames.map(f=>f.path)))].map(path=>new Promise((ok,no)=>{const im=new Image();im.onload=()=>{cache.set(path,im);ok()};im.onerror=no;im.src=path}))).then(()=>{draw();window.READY=true;requestAnimationFrame(tick)});window.study={data:D,choose,select(k){playing=false;fi=k;draw()},frame(i,k){draw(i,k);return c.toDataURL('image/png')},state(){return{ci,fi,playing,time,loops}}};</script></html>'''
(P/'core-review.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))));print(len(items),'candidate view/clips')
